// Thread block size
#define GROUP_SIZE 256

inline double dot (double4 &a, double4 &b)
{
  return (a.x * b.x + a.y * b.y) + (a.z * b.z + a.w * b.w);
}

inline double4 operator+(double4 a, double4 b)
{
  return {a.x + b.x, a.y + b.y, a.z + b.z, a.w + b.w};
}

inline double4 operator*(double b, double4 a)
{
  return {b * a.x, b * a.y, b * a.z, b * a.w};
}

inline int8 make_int8(int s)
{
  return {s,s,s,s,s,s,s,s};
}

// Calculates equivalent distribution 
#pragma omp declare target
double ced(double rho, double weight, double2 dir, double2 u)
{
  double u2 = (u.x * u.x) + (u.y * u.y);
  double eu = (dir.x * u.x) + (dir.y * u.y);
  return rho * weight * (1.0f + 3.0f * eu + 4.5f * eu * eu - 1.5f * u2);
}
#pragma omp end declare target

// convert_int8() may be language specific
inline int8 newPos (const int p, const double8 &dir)
{
  int8 np;
  np.s0 = p + (int)dir.s0;
  np.s1 = p + (int)dir.s1;
  np.s2 = p + (int)dir.s2;
  np.s3 = p + (int)dir.s3;
  np.s4 = p + (int)dir.s4;
  np.s5 = p + (int)dir.s5;
  np.s6 = p + (int)dir.s6;
  np.s7 = p + (int)dir.s7;
  return np;
}

inline int8 fma8 (const unsigned int &a, const int8 &b, const int8 &c)
{
  int8 r;
  r.s0 = a * b.s0 + c.s0;
  r.s1 = a * b.s1 + c.s1;
  r.s2 = a * b.s2 + c.s2;
  r.s3 = a * b.s3 + c.s3;
  r.s4 = a * b.s4 + c.s4;
  r.s5 = a * b.s5 + c.s5;
  r.s6 = a * b.s6 + c.s6;
  r.s7 = a * b.s7 + c.s7;
  return r;
}

void lbm (
    const unsigned int width,
    const unsigned int height,
    const double *__restrict if0,
          double *__restrict of0, 
    const double4 *__restrict if1234,
          double4 *__restrict of1234,
    const double4 *__restrict if5678,
          double4 *__restrict of5678,
    const bool *__restrict type,
    const double8 dirX,
    const double8 dirY,
    const double *__restrict weight,
    double omega)
{
  #pragma omp target teams distribute parallel for collapse(2) thread_limit(GROUP_SIZE)
  for (unsigned int idy = 0; idy < height; idy++) {
    for (unsigned int idx = 0; idx < width; idx++) {
      unsigned int pos = idx + width * idy;

      // Read input distributions
      double f0 = if0[pos];
      double4 f1234 = if1234[pos];
      double4 f5678 = if5678[pos];

      // intermediate results
      double e0;
      double4 e1234;
      double4 e5678;

      double rho; // Density
      double2 u;  // Velocity

      // Collide
      if(type[pos]) // Boundary
      {
        // Swap directions 
        // f1234.xyzw = f1234.zwxy;
        e1234.x = f1234.z;
        e1234.y = f1234.w;
        e1234.z = f1234.x;
        e1234.w = f1234.y;

        // f5678.xyzw = f5678.zwxy;
        e5678.x = f5678.z;
        e5678.y = f5678.w;
        e5678.z = f5678.x;
        e5678.w = f5678.y;

        rho = 0;
        u = {0, 0};
      }
      else // Fluid
      {
        // Compute rho and u
        // Rho is computed by doing a reduction on f
        double4 temp = f1234 + f5678;
        rho = f0 + temp.x + temp.y + temp.z + temp.w;

        // Compute velocity in x and y directions
        double4 x1234 = {dirX.s0, dirX.s1, dirX.s2, dirX.s3};
        double4 y1234 = {dirY.s0, dirY.s1, dirY.s2, dirY.s3};
        double4 x5678 = {dirX.s4, dirX.s5, dirX.s6, dirX.s7};
        double4 y5678 = {dirY.s4, dirY.s5, dirY.s6, dirY.s7};
        u.x = (dot(f1234, x1234) + dot(f5678, x5678)) / rho;
        u.y = (dot(f1234, y1234) + dot(f5678, y5678)) / rho;

        // Compute f
        e0 = ced(rho, weight[0], {0, 0}, u);
        e1234.x = ced(rho, weight[1], {dirX.s0, dirY.s0}, u);
        e1234.y = ced(rho, weight[2], {dirX.s1, dirY.s1}, u);
        e1234.z = ced(rho, weight[3], {dirX.s2, dirY.s2}, u);
        e1234.w = ced(rho, weight[4], {dirX.s3, dirY.s3}, u);
        e5678.x = ced(rho, weight[5], {dirX.s4, dirY.s4}, u);
        e5678.y = ced(rho, weight[6], {dirX.s5, dirY.s5}, u);
        e5678.z = ced(rho, weight[7], {dirX.s6, dirY.s6}, u);
        e5678.w = ced(rho, weight[8], {dirX.s7, dirY.s7}, u);

        e0 = (1.0 - omega) * f0 + omega * e0;
        e1234 = (1.0 - omega) * f1234 + omega * e1234;
        e5678 = (1.0 - omega) * f5678 + omega * e5678;
      }

      // Propagate
      bool t3 = idx > 0;          // Not on Left boundary
      bool t1 = idx < width - 1;  // Not on Right boundary
      bool t4 = idy > 0;          // Not on Upper boundary
      bool t2 = idy < height - 1; // Not on lower boundary

      if (t1 && t2 && t3 && t4) {
        // New positions to write (Each thread will write 8 values)
        // Note the propagation sources (e.g. f1234) imply the OLD locations for each thread
        int8 nX = newPos(idx, dirX);
        int8 nY = newPos(idy, dirY);
        int8 nPos = fma8(width, nY, nX);

        // Write center distribution to thread's location
        of0[pos] = e0;
      // Propagate to right cell
        of1234[nPos.s0].x = e1234.x;

      // Propagate to Lower cell
        of1234[nPos.s1].y = e1234.y;

      // Propagate to left cell
        of1234[nPos.s2].z = e1234.z;

      // Propagate to Upper cell
        of1234[nPos.s3].w = e1234.w;

      // Propagate to Lower-Right cell
        of5678[nPos.s4].x = e5678.x;

      // Propogate to Lower-Left cell
        of5678[nPos.s5].y = e5678.y;

      // Propagate to Upper-Left cell
        of5678[nPos.s6].z = e5678.z;

      // Propagate to Upper-Right cell
        of5678[nPos.s7].w = e5678.w;
      }
    }
  }
}

void fluidSim (
  const int iterations,
  const double omega,
  const int *dims,
  const bool *h_type,
  double2 *u,
  double *rho,
  const double8 dirX,
  const double8 dirY,
  const double h_weight[9],
        double *h_if0,
        double *h_if1234,
        double *h_if5678,
        double *h_of0,
        double *h_of1234,
        double *h_of5678)
{
  unsigned int width = dims[0];
  unsigned int height = dims[1]; 
  size_t temp = width * height;
  size_t dbl_size = temp * sizeof(double);
  size_t dbl4_size = dbl_size * 4;

  memcpy(h_of0, h_if0, dbl_size);
  memcpy(h_of1234, h_if1234, dbl4_size);
  memcpy(h_of5678, h_if5678, dbl4_size);

  #pragma omp target data map (to: h_if0[0:temp],\
                                   h_of0[0:temp],\
                                   h_if1234[0:temp*4],\
                                   h_of1234[0:temp*4],\
                                   h_if5678[0:temp*4],\
                                   h_of5678[0:temp*4],\
                                   h_weight[0:9],\
                                   h_type[0:temp])
  {
    auto start = std::chrono::steady_clock::now();

    for(int i = 0; i < iterations; ++i) {
      lbm(width, height, h_if0, h_of0, 
          (double4*)h_if1234, (double4*)h_of1234,
          (double4*)h_if5678, (double4*)h_of5678, 
          h_type, dirX, dirY, h_weight, omega
      );

      // Swap device buffers
      auto temp0 = h_of0;
      auto temp1234 = h_of1234;
      auto temp5678 = h_of5678;

      h_of0 = h_if0;
      h_of1234 = h_if1234;
      h_of5678 = h_if5678;

      h_if0 = temp0;
      h_if1234 = temp1234;
      h_if5678 = temp5678;
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time %f (s)\n", (time * 1e-9f) / iterations);

    #pragma omp target update from (h_if0[0:temp])
    #pragma omp target update from (h_if1234[0:temp*4])
    #pragma omp target update from (h_if5678[0:temp*4])
  }

  if (iterations % 2 == 0) {
    memcpy(h_of0, h_if0, dbl_size);
    memcpy(h_of1234, h_if1234, dbl4_size);
    memcpy(h_of5678, h_if5678, dbl4_size);
  }
}

#include <stdio.h>
#include <stdlib.h> 
#include <chrono>
#include <omp.h>

typedef unsigned long ulong;

ulong * convertBuffer2Array (char *cbuffer, unsigned size, unsigned step)
{
  unsigned i,j; 
  ulong * values = NULL;
  posix_memalign((void**)&values, 1024, sizeof(ulong)*size/step);
  for (i = 0; i < size / step; i++) {
    values[i] = 0;    // Initialize all elements to zero.
  }
  for (i = 0; i < size; i += step ){
    for (j = 0; j < step; j++){
      values[i / step] += (ulong)((unsigned char)cbuffer[i + j]) << (8*j);
    }
  }
  return values;
}

#pragma omp declare target
unsigned my_abs ( int x )
{
  unsigned t = x >> 31;
  return (x ^ t) - t;
}

unsigned FPCCompress(ulong *values, unsigned size )
{
  unsigned compressable = 0;
  unsigned i;
  for (i = 0; i < size; i++) {
    // 000
    if(values[i] == 0){
      compressable += 1;
      continue;
    }
    // 001 010
    if(my_abs((int)(values[i])) <= 0xFF){
      compressable += 1;
      continue;
    }
    // 011
    if(my_abs((int)(values[i])) <= 0xFFFF){
      compressable += 2;
      continue;
    }
    //100  
    if(((values[i]) & 0xFFFF) == 0 ){
      compressable += 2;
      continue;
    }
    //101
    if( my_abs((int)((values[i]) & 0xFFFF)) <= 0xFF
        && my_abs((int)((values[i] >> 16) & 0xFFFF)) <= 0xFF){
      compressable += 2;
      continue;
    }
    //110
    unsigned byte0 = (values[i]) & 0xFF;
    unsigned byte1 = (values[i] >> 8) & 0xFF;
    unsigned byte2 = (values[i] >> 16) & 0xFF;
    unsigned byte3 = (values[i] >> 24) & 0xFF;
    if(byte0 == byte1 && byte0 == byte2 && byte0 == byte3){
      compressable += 1;
      continue;
    }
    //111
    compressable += 4;
  }
  return compressable;
}

unsigned f1(ulong value, bool* mask) {
  if (value == 0) {
    *mask = 1;
  } 
  return 1;
}

unsigned f2(ulong value, bool* mask) {
  if (my_abs((int)(value)) <= 0xFF) *mask = 1;
  return 1;
}

unsigned f3(ulong value, bool* mask) {
  if (my_abs((int)(value)) <= 0xFFFF) *mask = 1;
  return 2;
}

unsigned f4(ulong value, bool* mask) {
  if (((value) & 0xFFFF) == 0 ) *mask = 1;
  return 2;
}

unsigned f5(ulong value, bool* mask) {
  if ((my_abs((int)((value) & 0xFFFF))) <= 0xFF && 
      my_abs((int)((value >> 16) & 0xFFFF)) <= 0xFF) 
    *mask = 1;
  return 2;
}

unsigned f6(ulong value, bool* mask) {
  unsigned byte0 = (value) & 0xFF;
  unsigned byte1 = (value >> 8) & 0xFF;
  unsigned byte2 = (value >> 16) & 0xFF;
  unsigned byte3 = (value >> 24) & 0xFF;
  if (byte0 == byte1 && byte0 == byte2 && byte0 == byte3) 
    *mask = 1;
  return 1;
}

unsigned f7(ulong value, bool* mask) {
  *mask = 1;
  return 4;
}
#pragma omp end declare target

void fpc (const ulong* values, unsigned *cmp_size, const int values_size, const int wgs)
{
  *cmp_size= 0;
  #pragma omp target data map(to: values[0:values_size]) map(tofrom: cmp_size[0:1])
  {
    #pragma omp target teams num_teams(values_size/wgs) thread_limit(wgs) 
    {
      unsigned compressable;
      #pragma omp parallel
      {
        int lid = omp_get_thread_num();
        int WGS = omp_get_num_threads();
        int gid = omp_get_team_num()*WGS+lid;

        ulong value = values[gid];
        unsigned inc;

        // 000
        if (value == 0){
          inc = 1;
        }
        // 001 010
        else if ((my_abs((int)(value)) <= 0xFF)) {
          inc = 1;
        }
        // 011
        else if ((my_abs((int)(value)) <= 0xFFFF)) {
          inc = 2;
        }
        //100  
        else if ((((value) & 0xFFFF) == 0 )) {
          inc = 2;
        }
        //101
        else if ((my_abs((int)((value) & 0xFFFF))) <= 0xFF
            && my_abs((int)((value >> 16) & 0xFFFF)) <= 0xFF ) {
          inc = 2;
        }
        //110
        else if( (((value) & 0xFF) == ((value >> 8) & 0xFF)) &&
            (((value) & 0xFF) == ((value >> 16) & 0xFF)) &&
            (((value) & 0xFF) == ((value >> 24) & 0xFF)) ) {
          inc = 1;
        } else { 
          inc = 4;
        }

        if (lid == 0) compressable = 0;
        #pragma omp barrier

        #pragma omp atomic update 
        compressable += inc;
        #pragma omp barrier
        if (lid == WGS-1) {
        #pragma omp atomic update 
          cmp_size[0] += compressable;
        }
      }
    }
  }
}

void fpc2 (const ulong* values, unsigned *cmp_size, const int values_size, const int wgs)
{
  *cmp_size= 0;
  #pragma omp target data map(to: values[0:values_size]) map(tofrom: cmp_size[0:1])
  {
    #pragma omp target teams num_teams(values_size/wgs) thread_limit(wgs)
    {
      unsigned compressable;
      #pragma omp parallel
      {
        int lid = omp_get_thread_num();
        int WGS = omp_get_num_threads();
        int gid = omp_get_team_num()*WGS+lid;

        ulong value = values[gid];

        unsigned inc;

        bool m1 = 0;
        bool m2 = 0;
        bool m3 = 0;
        bool m4 = 0;
        bool m5 = 0;
        bool m6 = 0;
        bool m7 = 0;

        unsigned inc1 = f1(value, &m1);
        unsigned inc2 = f2(value, &m2);
        unsigned inc3 = f3(value, &m3);
        unsigned inc4 = f4(value, &m4);
        unsigned inc5 = f5(value, &m5);
        unsigned inc6 = f6(value, &m6);
        unsigned inc7 = f7(value, &m7);

        if (m1)
          inc = inc1;
        else if (m2)
          inc = inc2;
        else if (m3)
          inc = inc3;
        else if (m4)
          inc = inc4;
        else if (m5)
          inc = inc5;
        else if (m6)
          inc = inc6;
        else
          inc = inc7;

        if (lid == 0) compressable = 0;
        #pragma omp barrier

        #pragma omp atomic update 
        compressable += inc;

        #pragma omp barrier
        if (lid == WGS-1) {
          #pragma omp atomic update 
          cmp_size[0] += compressable;
        }
      }
    }
  }
}


int main(int argc, char** argv) {
  if (argc != 3) {
    printf("Usage: %s <work-group size> <repeat>\n", argv[0]);
    return 1;
  }
  const int wgs = atoi(argv[1]); 
  const int repeat = atoi(argv[2]);

  // create the char buffer
  const int step = 4;
  const size_t size = (size_t)wgs * wgs * wgs;
  char* cbuffer = (char*) malloc (size * step);

  srand(2);
  for (int i = 0; i < size*step; i++) {
    cbuffer[i] = 0xFF << (rand() % 256);
  }

  ulong *values = convertBuffer2Array (cbuffer, size, step);
  unsigned values_size = size / step;

  // run on the host
  unsigned cmp_size = FPCCompress(values, values_size);

  // run on the device
  unsigned cmp_size_hw; 

  bool ok = true;

  // warmup
  fpc(values, &cmp_size_hw, values_size, wgs);

  auto start = std::chrono::high_resolution_clock::now();

  for (int i = 0; i < repeat; i++) {
    fpc(values, &cmp_size_hw, values_size, wgs);
    if (cmp_size_hw != cmp_size) {
      printf("fpc failed %u != %u\n", cmp_size_hw, cmp_size);
      ok = false;
      break;
    }
  }

  auto end = std::chrono::high_resolution_clock::now();
  auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
  printf("fpc: average device offload time %f (s)\n", (time * 1e-9f) / repeat);

  // warmup
  fpc2(values, &cmp_size_hw, values_size, wgs);

  start = std::chrono::high_resolution_clock::now();

  for (int i = 0; i < repeat; i++) {
    fpc2(values, &cmp_size_hw, values_size, wgs);
    if (cmp_size_hw != cmp_size) {
      printf("fpc2 failed %u != %u\n", cmp_size_hw, cmp_size);
      ok = false;
      break;
    }
  }

  end = std::chrono::high_resolution_clock::now();
  time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
  printf("fpc2: average device offload time %f (s)\n", (time * 1e-9f) / repeat);

  printf("%s\n", ok ? "PASS" : "FAIL");

  free(values);
  free(cbuffer);
  return 0;
}

/** Modifed version of knn-CUDA from https://github.com/vincentfpgarcia/kNN-CUDA
 * The modifications are
 *      removed texture memory usage
 *      removed split query KNN computation
 *      added feature extraction with bilinear interpolation
 *
 * Last modified by Christopher B. Choy <chrischoy@ai.stanford.edu> 12/23/2016
 */

// Includes
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>
#include <omp.h>

// Constants used by the program
#define BLOCK_DIM 16

//-----------------------------------------------------------------------------------------------//
//                                   K-th NEAREST NEIGHBORS //
//-----------------------------------------------------------------------------------------------//

float compute_distance(const float *ref, int ref_nb, const float *query,
                       int query_nb, int dim, int ref_index, int query_index) {
  float sum = 0.f;
  for (int d = 0; d < dim; ++d) {
    const float diff =
        ref[d * ref_nb + ref_index] - query[d * query_nb + query_index];
    sum += diff * diff;
  }
  return sqrtf(sum);
}

void modified_insertion_sort(float *dist, int *index, int length, int k) {

  // Initialise the first index
  index[0] = 0;

  // Go through all points
  for (int i = 1; i < length; ++i) {

    // Store current distance and associated index
    float curr_dist = dist[i];
    int curr_index = i;

    // Skip the current value if its index is >= k and if it's higher the k-th
    // slready sorted mallest value
    if (i >= k && curr_dist >= dist[k - 1]) {
      continue;
    }

    // Shift values (and indexes) higher that the current distance to the right
    int j = i < k - 1 ? i : k-1;
    while (j > 0 && dist[j - 1] > curr_dist) {
      dist[j] = dist[j - 1];
      index[j] = index[j - 1];
      --j;
    }

    // Write the current distance and index at their position
    dist[j] = curr_dist;
    index[j] = curr_index;
  }
}

bool knn_serial(const float *ref, int ref_nb, const float *query, int query_nb,
           int dim, int k, float *knn_dist, int *knn_index) {
  // Allocate local array to store all the distances / indexes for a given query
  // point
  float *dist = (float *)malloc(ref_nb * sizeof(float));
  int *index = (int *)malloc(ref_nb * sizeof(int));

  // Allocation checks
  if (!dist || !index) {
    printf("Memory allocation error\n");
    free(dist);
    free(index);
    return false;
  }

  // Process one query point at the time
  for (int i = 0; i < query_nb; ++i) {

    // Compute all distances / indexes
    for (int j = 0; j < ref_nb; ++j) {
      dist[j] = compute_distance(ref, ref_nb, query, query_nb, dim, j, i);
      index[j] = j;
    }

    // Sort distances / indexes
    modified_insertion_sort(dist, index, ref_nb, k);

    // Copy k smallest distances and their associated index
    for (int j = 0; j < k; ++j) {
      knn_dist[j * query_nb + i] = dist[j];
      knn_index[j * query_nb + i] = index[j];
    }
  }

  // Memory clean-up
  free(dist);
  free(index);
  return true;
}

int main(int argc, char* argv[]) {
  if (argc != 2) {
    printf("Usage: %s <repeat>\n", argv[0]);
    return 1;
  }
  const int iterations = atoi(argv[1]);

  float *ref;          // Pointer to reference point array
  float *query;        // Pointer to query point array
  float *dist;         // Pointer to distance array
  int *ind;            // Pointer to index array
  int ref_nb = 4096;   // Reference point number, max=65535
  int query_nb = 4096; // Query point number,     max=65535
  int dim = 68;        // Dimension of points
  int k = 20;          // Nearest neighbors to consider
  int c_iterations = 1;
  int i;
  const float precision = 0.001f; // distance error max
  int nb_correct_precisions = 0;
  int nb_correct_indexes = 0;
  // Memory allocation
  ref = (float *)malloc(ref_nb * dim * sizeof(float));
  query = (float *)malloc(query_nb * dim * sizeof(float));
  //dist = (float *)malloc(query_nb * k * sizeof(float));
  dist = (float *)malloc(query_nb * ref_nb * sizeof(float));
  ind = (int *)malloc(query_nb * k * sizeof(float));

  // Init
  srand(2);
  for (i = 0; i < ref_nb * dim; i++)
    ref[i] = (float)rand() / (float)RAND_MAX;
  for (i = 0; i < query_nb * dim; i++)
    query[i] = (float)rand() / (float)RAND_MAX;

  // Display informations
  printf("Number of reference points      : %6d\n", ref_nb);
  printf("Number of query points          : %6d\n", query_nb);
  printf("Dimension of points             : %4d\n", dim);
  printf("Number of neighbors to consider : %4d\n", k);
  printf("Processing kNN search           :\n");

  float *knn_dist = (float *)malloc(query_nb * k * sizeof(float));
  int *knn_index = (int *)malloc(query_nb * k * sizeof(int));
  printf("Ground truth computation in progress...\n\n");
  if (!knn_serial(ref, ref_nb, query, query_nb, dim, k, knn_dist, knn_index)) {
    free(ref);
    free(query);
    free(knn_dist);
    free(knn_index);
    return EXIT_FAILURE;
  }

  struct timeval tic;
  struct timeval toc;
  float elapsed_time;

  printf("On CPU: \n");
  gettimeofday(&tic, NULL);
  for (i = 0; i < c_iterations; i++) {
    knn_serial(ref, ref_nb, query, query_nb, dim, k, dist, ind);
  }
  gettimeofday(&toc, NULL);
  elapsed_time = toc.tv_sec - tic.tv_sec;
  elapsed_time += (toc.tv_usec - tic.tv_usec) / 1000000.;
  printf(" done in %f s for %d iterations (%f s by iteration)\n", elapsed_time,
         c_iterations, elapsed_time / (c_iterations));

  printf("on GPU: \n");
  gettimeofday(&tic, NULL);

  for (i = 0; i < iterations; i++) {
    #pragma omp target data map(to: ref[0:ref_nb * dim], query[0:query_nb * dim]) \
                          map(alloc: dist[0:query_nb * ref_nb], ind[0:query_nb * k])
    {
      // Kernel 1: Compute all the distances
      #pragma omp target teams num_teams((ref_nb + 15)*(query_nb + 15)/256) thread_limit(256) 
      {
        float shared_A[BLOCK_DIM*BLOCK_DIM];
        float shared_B[BLOCK_DIM*BLOCK_DIM];
        int begin_A;
        int begin_B;
        int step_A;
        int step_B;
        int end_A;

        #pragma omp parallel 
        {
          // Thread index
          int tx = omp_get_thread_num() % 16;
          int ty = omp_get_thread_num() / 16;

          // Other variables
          float tmp;
          float ssd = 0;

          // Loop parameters
          begin_A = BLOCK_DIM * (omp_get_team_num() / ((query_nb+15)/16));
          begin_B = BLOCK_DIM * (omp_get_team_num() % ((query_nb+15)/16));
          step_A  = BLOCK_DIM * ref_nb;
          step_B  = BLOCK_DIM * query_nb;
          end_A   = begin_A + (dim - 1) * ref_nb;

          // Conditions
          int cond0 = (begin_A + tx < ref_nb); // used to write in shared memory
          int cond1 = (begin_B + tx < query_nb); // used to write in shared memory & to
                                           // computations and to write in output matrix
          int cond2 =
              (begin_A + ty < ref_nb); // used to computations and to write in output matrix

          // Loop over all the sub-matrices of A and B required to compute the block
          // sub-matrix
          for (int a = begin_A, b = begin_B; 
                   a <= end_A; a += step_A, b += step_B) {
            // Load the matrices from device memory to shared memory; each thread loads
            // one element of each matrix
            if (a / ref_nb + ty < dim) {
              shared_A[ty*BLOCK_DIM+tx] = (cond0) ? ref[a + ref_nb * ty + tx] : 0;
              shared_B[ty*BLOCK_DIM+tx] = (cond1) ? query[b + query_nb * ty + tx] : 0;
            } else {
              shared_A[ty*BLOCK_DIM+tx] = 0;
              shared_B[ty*BLOCK_DIM+tx] = 0;
            }

            // Synchronize to make sure the matrices are loaded
            #pragma omp barrier

            // Compute the difference between the two matrixes; each thread computes one
            // element of the block sub-matrix
            if (cond2 && cond1) {
              for (int k = 0; k < BLOCK_DIM; ++k) {
                tmp = shared_A[k*BLOCK_DIM+ty] - shared_B[k*BLOCK_DIM+tx];
                ssd += tmp * tmp;
              }
            }

            // Synchronize to make sure that the preceding computation is done before
            // loading two new sub-matrices of A and B in the next iteration
            #pragma omp barrier
          }

          // Write the block sub-matrix to device memory; each thread writes one element
          if (cond2 && cond1) dist[(begin_A + ty) * query_nb + begin_B + tx] = ssd;
        }
      }

      // Kernel 2: Sort each column
      #pragma omp target teams distribute parallel for thread_limit(256)
      for (unsigned int xIndex = 0; xIndex < query_nb; xIndex++) {
        // Pointer shift, initialization, and max value
        float* p_dist = &dist[xIndex];
        int* p_ind = &ind[xIndex];
        float max_dist = p_dist[0];
        p_ind[0] = 0;

        // Part 1 : sort kth firt elementZ
        for (int l = 1; l < k; l++) {
          int curr_row = l * query_nb;
          float curr_dist = p_dist[curr_row];
          if (curr_dist < max_dist) {
            int i = l - 1;
            for (int a = 0; a < l - 1; a++) {
              if (p_dist[a * query_nb] > curr_dist) {
                i = a;
                break;
              }
            }
            for (int j = l; j > i; j--) {
              p_dist[j * query_nb] = p_dist[(j - 1) * query_nb];
              p_ind[j * query_nb] = p_ind[(j - 1) * query_nb];
            }
            p_dist[i * query_nb] = curr_dist;
            p_ind[i * query_nb] = l;
          } else {
            p_ind[l * query_nb] = l;
          }
          max_dist = p_dist[curr_row];
        }

        // Part 2 : insert element in the k-th first lines
        int max_row = (k - 1) * query_nb;
        for (int l = k; l < ref_nb; l++) {
          float curr_dist = p_dist[l * query_nb];
          if (curr_dist < max_dist) {
            int i = k - 1;
            for (int a = 0; a < k - 1; a++) {
              if (p_dist[a * query_nb] > curr_dist) {
                i = a;
                break;
              }
            }
            for (int j = k - 1; j > i; j--) {
              p_dist[j * query_nb] = p_dist[(j - 1) * query_nb];
              p_ind[j * query_nb] = p_ind[(j - 1) * query_nb];
            }
            p_dist[i * query_nb] = curr_dist;
            p_ind[i * query_nb] = l;
            max_dist = p_dist[max_row];
          }
        }
      }

      // Kernel 3: Compute square root of k first elements
      #pragma omp target teams distribute parallel for thread_limit(256)
      for (unsigned int i = 0; i < query_nb * k; i++)
        dist[i] = sqrtf(dist[i]);

      #pragma omp target update from (dist[0:query_nb * k]) 
      #pragma omp target update from (ind[0:query_nb * k])
    }
  }

  gettimeofday(&toc, NULL);
  elapsed_time = toc.tv_sec - tic.tv_sec;
  elapsed_time += (toc.tv_usec - tic.tv_usec) / 1000000.;
  printf(" done in %f s for %d iterations (%f s by iteration)\n", elapsed_time,
         iterations, elapsed_time / (iterations));

  for (int i = 0; i < query_nb * k; ++i) {
    if (fabs(dist[i] - knn_dist[i]) <= precision) {
      nb_correct_precisions++;
    }
    if (ind[i] == knn_index[i]) {
      nb_correct_indexes++;
    }
  }

  float precision_accuracy = nb_correct_precisions / ((float)query_nb * k);
  float index_accuracy = nb_correct_indexes / ((float)query_nb * k);
  printf("Precision accuracy %f\nIndex accuracy %f\n", precision_accuracy, index_accuracy);
  printf("%s\n", (precision_accuracy == 1.f) ? "PASS" : "FAIL");

  free(ind);
  free(dist);
  free(query);
  free(ref);
}

/** GPU solver for 2D lid-driven cavity problem, using finite difference method
 * \file main_gpu.cpp
 *
 * Solve the incompressible, isothermal 2D Navier–Stokes equations for a square
 * lid-driven cavity on a GPU (via CUDA), using the finite difference method.
 * To change the grid resolution, modify "NUM". In addition, the problem is controlled
 * by the Reynolds number ("Re_num").
 * 
 * Based on the methodology given in Chapter 3 of "Numerical Simulation in Fluid
 * Dynamics", by M. Griebel, T. Dornseifer, and T. Neunhoeffer. SIAM, Philadelphia,
 * PA, 1998.
 * 
 * Boundary conditions:
 * u = 0 and v = 0 at x = 0, x = L, y = 0
 * u = ustar at y = H
 * v = 0 at y = H
 */

#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <chrono>
#include <omp.h>

/** Problem size along one side; total number of cells is this squared */
#define NUM 512

// block size
#define BLOCK_SIZE 128

/** Double precision */
#define DOUBLE

#ifdef DOUBLE
#define Real double

#define ZERO 0.0
#define ONE 1.0
#define TWO 2.0
#define FOUR 4.0

#define SMALL 1.0e-10;

/** Reynolds number */
const Real Re_num = 1000.0;

/** SOR relaxation parameter */
const Real omega = 1.7;

/** Discretization mixture parameter (gamma) */
const Real mix_param = 0.9;

/** Safety factor for time step modification */
const Real tau = 0.5;

/** Body forces in x- and y- directions */
const Real gx = 0.0;
const Real gy = 0.0;

/** Domain size (non-dimensional) */
#define xLength 1.0
#define yLength 1.0

#else

#define Real float

// replace double functions with float versions
#undef fmin
#define fmin fminf
#undef fmax
#define fmax fmaxf
#undef fabs
#define fabs fabsf
#undef sqrt
#define sqrt sqrtf

#define ZERO 0.0f
#define ONE 1.0f
#define TWO 2.0f
#define FOUR 4.0f
#define SMALL 1.0e-10f;

/** Reynolds number */
const Real Re_num = 1000.0f;

/** SOR relaxation parameter */
const Real omega = 1.7f;

/** Discretization mixture parameter (gamma) */
const Real mix_param = 0.9f;

/** Safety factor for time step modification */
const Real tau = 0.5f;

/** Body forces in x- and y- directions */
const Real gx = 0.0f;
const Real gy = 0.0f;

/** Domain size (non-dimensional) */
#define xLength 1.0f
#define yLength 1.0f
#endif

/** Mesh sizes */
const Real dx = xLength / NUM;
const Real dy = yLength / NUM;

/** Max macro (type safe, from GNU) */
//#define MAX(a,b) ({ __typeof__ (a) _a = (a); __typeof__ (b) _b = (b); _a > _b ? _a : _b; })

/** Min macro (type safe) */
//#define MIN(a,b) ({ __typeof__ (a) _a = (a); __typeof__ (b) _b = (b); _a < _b ? _a : _b; })

// map two-dimensional indices to one-dimensional memory
#define u(I, J) u[((I) * ((NUM) + 2)) + (J)]
#define v(I, J) v[((I) * ((NUM) + 2)) + (J)]
#define F(I, J) F[((I) * ((NUM) + 2)) + (J)]
#define G(I, J) G[((I) * ((NUM) + 2)) + (J)]
#define pres_red(I, J) pres_red[((I) * ((NUM_2) + 2)) + (J)]
#define pres_black(I, J) pres_black[((I) * ((NUM_2) + 2)) + (J)]

///////////////////////////////////////////////////////////////////////////////
void set_BCs_host (Real* u, Real* v) 
{
  int ind;

  // loop through rows and columns
  for (ind = 0; ind < NUM + 2; ++ind) {

    // left boundary
    u(0, ind) = ZERO;
    v(0, ind) = -v(1, ind);

    // right boundary
    u(NUM, ind) = ZERO;
    v(NUM + 1, ind) = -v(NUM, ind);

    // bottom boundary
    u(ind, 0) = -u(ind, 1);
    v(ind, 0) = ZERO;

    // top boundary
    u(ind, NUM + 1) = TWO - u(ind, NUM);
    v(ind, NUM) = ZERO;

    if (ind == NUM) {
      // left boundary
      u(0, 0) = ZERO;
      v(0, 0) = -v(1, 0);
      u(0, NUM + 1) = ZERO;
      v(0, NUM + 1) = -v(1, NUM + 1);

      // right boundary
      u(NUM, 0) = ZERO;
      v(NUM + 1, 0) = -v(NUM, 0);
      u(NUM, NUM + 1) = ZERO;
      v(NUM + 1, NUM + 1) = -v(NUM, NUM + 1);

      // bottom boundary
      u(0, 0) = -u(0, 1);
      v(0, 0) = ZERO;
      u(NUM + 1, 0) = -u(NUM + 1, 1);
      v(NUM + 1, 0) = ZERO;

      // top boundary
      u(0, NUM + 1) = TWO - u(0, NUM);
      v(0, NUM) = ZERO;
      u(NUM + 1, NUM + 1) = TWO - u(NUM + 1, NUM);
      v(ind, NUM + 1) = ZERO;
    } // end if

  } // end for

} // end set_BCs_host

