int main (int argc, char *argv[])
{
  // iterations for Red-Black Gauss-Seidel with SOR
  int iter = 0;

  const int it_max = 1000000;

  // SOR iteration tolerance
  const Real tol = 0.001;

  // time range
  const Real time_start = 0.0;
  const Real time_end = 0.001; //20.0;

  // initial time step size
  Real dt = 0.02;

  int size = (NUM + 2) * (NUM + 2);
  int size_pres = ((NUM / 2) + 2) * (NUM + 2);

  // arrays for pressure and velocity
  Real* F;
  Real* u;
  Real* G;
  Real* v;

  F = (Real *) calloc (size, sizeof(Real));
  u = (Real *) calloc (size, sizeof(Real));
  G = (Real *) calloc (size, sizeof(Real));
  v = (Real *) calloc (size, sizeof(Real));

  for (int i = 0; i < size; ++i) {
    F[i] = ZERO;
    u[i] = ZERO;
    G[i] = ZERO;
    v[i] = ZERO;
  }

  // arrays for pressure
  Real* pres_red;
  Real* pres_black;

  pres_red = (Real *) calloc (size_pres, sizeof(Real));
  pres_black = (Real *) calloc (size_pres, sizeof(Real));

  for (int i = 0; i < size_pres; ++i) {
    pres_red[i] = ZERO;
    pres_black[i] = ZERO;
  }

  // print problem size
  printf("Problem size: %d x %d \n", NUM, NUM);

  // residual variable
  Real* res_arr;

  int size_res = NUM / (2 * BLOCK_SIZE) * NUM;
  res_arr = (Real *) calloc (size_res, sizeof(Real));

  // variables to store maximum velocities
  Real* max_u_arr;
  Real* max_v_arr;
  int size_max = size_res;

  max_u_arr = (Real *) calloc (size_max, sizeof(Real));
  max_v_arr = (Real *) calloc (size_max, sizeof(Real));

  // pressure sum
  Real* pres_sum;
  pres_sum = (Real *) calloc (size_res, sizeof(Real));

  // set initial BCs
  set_BCs_host (u, v);

  Real max_u = SMALL;
  Real max_v = SMALL;
  // get max velocity for initial values (including BCs)
  #pragma unroll
  for (int col = 0; col < NUM + 2; ++col) {
    #pragma unroll
    for (int row = 1; row < NUM + 2; ++row) {
      max_u = fmax(max_u, fabs( u(col, row) ));
    }
  }

  #pragma unroll
  for (int col = 1; col < NUM + 2; ++col) {
    #pragma unroll
    for (int row = 0; row < NUM + 2; ++row) {
      max_v = fmax(max_v, fabs( v(col, row) ));
    }
  }

#pragma omp target data map(tofrom: u[0:size], \
                                    v[0:size], \
                                    pres_red[0:size_pres], \
                                    pres_black[0:size_pres]) \
                        map(to: F[0:size], G[0:size]) \
                        map(alloc: pres_sum[0:size_res], \
                                   res_arr[0:size_res], \
                                   max_u_arr[0:size_max],\
                                   max_v_arr[0:size_max])
  {
    Real time = time_start;

    // time-step size based on grid and Reynolds number
    Real dt_Re = 0.5 * Re_num / ((1.0 / (dx * dx)) + (1.0 / (dy * dy)));

    auto start = std::chrono::steady_clock::now();

    // time iteration loop
    while (time < time_end) {

      // calculate time step based on stability and CFL
      dt = fmin((dx / max_u), (dy / max_v));
      dt = tau * fmin(dt_Re, dt);

      if ((time + dt) >= time_end) {
        dt = time_end - time;
      }

      // calculate F and G    
      //calculate_F <<<grid_F, block_F>>> (dt, u_d, v_d, F_d);
      #include "calculate_F.h"

      //    calculate_G <<<grid_G, block_G>>> (dt, u_d, v_d, G_d);
      #include "calculate_G.h"

      // get L2 norm of initial pressure
      //sum_pressure <<<grid_pr, block_pr>>> (pres_red_d, pres_black_d, pres_sum_d);
      #include "sum_pressure.h"

      //cudaMemcpy (pres_sum, pres_sum_d, size_res * sizeof(Real), cudaMemcpyDeviceToHost);
      #pragma omp target update from(pres_sum[0:size_res])

      Real p0_norm = ZERO;
      #pragma unroll
      for (int i = 0; i < size_res; ++i) {
        p0_norm += pres_sum[i];
      }
      //printf("p_norm = %lf\n", p0_norm);

      p0_norm = sqrt(p0_norm / ((Real)(NUM * NUM)));
      if (p0_norm < 0.0001) {
        p0_norm = 1.0;
      }

      Real norm_L2;

      // calculate new pressure
      // red-black Gauss-Seidel with SOR iteration loop
      for (iter = 1; iter <= it_max; ++iter) {

        // set pressure boundary conditions
        //set_horz_pres_BCs <<<grid_hpbc, block_hpbc>>> (pres_red_d, pres_black_d);
        #include "set_horz_pres_BCs.h"

        //      set_vert_pres_BCs <<<grid_vpbc, block_hpbc>>> (pres_red_d, pres_black_d);
        #include "set_vert_pres_BCs.h"

        // update red cells
        //      red_kernel <<<grid_pr, block_pr>>> (dt, F_d, G_d, pres_black_d, pres_red_d);
        #include "red_kernel.h"

        // update black cells
        //      black_kernel <<<grid_pr, block_pr>>> (dt, F_d, G_d, pres_red_d, pres_black_d);
        #include "black_kernel.h"

        // calculate residual values
        //calc_residual <<<grid_pr, block_pr>>> (dt, F_d, G_d, pres_red_d, pres_black_d, res_d);
        #include "calc_residual.h"

        #pragma omp target update from (res_arr[0:size_res])
        // transfer residual value(s) back to CPU
        //      cudaMemcpy (res, res_d, size_res * sizeof(Real), cudaMemcpyDeviceToHost);

        norm_L2 = ZERO;

        #pragma unroll
        for (int i = 0; i < size_res; ++i) {
          norm_L2 += res_arr[i];
        }

      //printf("norm_L2 = %lf\n", norm_L2);

        // calculate residual
        norm_L2 = sqrt(norm_L2 / ((Real)(NUM * NUM))) / p0_norm;

        // if tolerance has been reached, end SOR iterations
        if (norm_L2 < tol) {
          break;
        }  
      } // end for

      printf("Time = %f, delt = %e, iter = %i, res = %e\n", time + dt, dt, iter, norm_L2);

      // calculate new velocities and transfer maximums back

      //calculate_u <<<grid_pr, block_pr>>> (dt, F_d, pres_red_d, pres_black_d, u_d, max_u_d);
      #include "calculate_u.h"

      //    cudaMemcpy (max_u_arr, max_u_d, size_max * sizeof(Real), cudaMemcpyDeviceToHost);
      #pragma omp target update from(max_u_arr[0:size_max])

      //    calculate_v <<<grid_pr, block_pr>>> (dt, G_d, pres_red_d, pres_black_d, v_d, max_v_d);
      #include "calculate_v.h"

      //    cudaMemcpy (max_v_arr, max_v_d, size_max * sizeof(Real), cudaMemcpyDeviceToHost);
      #pragma omp target update from(max_v_arr[0:size_max])

      // get maximum u- and v- velocities
      max_v = SMALL;
      max_u = SMALL;

      #pragma unroll
      for (int i = 0; i < size_max; ++i) {
        Real test_u = max_u_arr[i];
        max_u = fmax(max_u, test_u);

        Real test_v = max_v_arr[i];
        max_v = fmax(max_v, test_v);
      }

      // set velocity boundary conditions
      //set_BCs <<<grid_bcs, block_bcs>>> (u_d, v_d);
      #include "set_BCs.h"

      // increase time
      time += dt;

      // single time step
      //break;

    } // end while

    auto end = std::chrono::steady_clock::now();
    auto elapsed_time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("\nTotal execution time of the iteration loop: %f (s)\n", elapsed_time * 1e-9f);
  }
  // transfer final temperature values back implicitly

  // write data to file
  FILE * pfile;
  pfile = fopen("velocity_gpu.dat", "w");
  fprintf(pfile, "#x\ty\tu\tv\n");
  if (pfile != NULL) {
    for (int row = 0; row < NUM; ++row) {
      for (int col = 0; col < NUM; ++col) {

        Real u_ij = u[(col * NUM) + row];
        Real u_im1j;
        if (col == 0) {
          u_im1j = 0.0;
        } else {
          u_im1j = u[(col - 1) * NUM + row];
        }

        u_ij = (u_ij + u_im1j) / 2.0;

        Real v_ij = v[(col * NUM) + row];
        Real v_ijm1;
        if (row == 0) {
          v_ijm1 = 0.0;
        } else {
          v_ijm1 = v[(col * NUM) + row - 1];
        }

        v_ij = (v_ij + v_ijm1) / 2.0;

        fprintf(pfile, "%f\t%f\t%f\t%f\n", ((Real)col + 0.5) * dx, ((Real)row + 0.5) * dy, u_ij, v_ij);
      }
    }
  }

  fclose(pfile);

  free(pres_red);
  free(pres_black);
  free(u);
  free(v);
  free(F);
  free(G);
  free(max_u_arr);
  free(max_v_arr);
  free(res_arr);
  free(pres_sum);
  return 0;
}

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <chrono>
#include "linear.h"
#include "kernel.h"

#define local_size TEMP_WORKGROUP_SIZE 

int cpu_offset;

void linear_regressionOMP(data_t* dataset, sum_t* result, int gpu_size, int global_size)
{
  sum_t* interns = (sum_t*)malloc(sizeof(sum_t) * local_size);

  for (int group_id = (gpu_size / local_size); group_id < (global_size / local_size); group_id++) {
    for (int loc_id = local_size - 1; loc_id >= 0; loc_id--) {
      int glob_id = loc_id + group_id * local_size;
      interns[loc_id].x = dataset[glob_id].x;
      interns[loc_id].y = dataset[glob_id].y;
      interns[loc_id].z = (dataset[glob_id].x * dataset[glob_id].y);
      interns[loc_id].w = (dataset[glob_id].x * dataset[glob_id].x);
      for (int i = (local_size / 2), old_i = local_size; i > 0; old_i = i, i /= 2) {
        if (loc_id < i) {
          interns[loc_id].x += interns[loc_id + i].x;
          interns[loc_id].y += interns[loc_id + i].y;
          interns[loc_id].z += interns[loc_id + i].z;
          interns[loc_id].w += interns[loc_id + i].w;
          if (loc_id == (i - 1) && old_i % 2 != 0) {
            interns[loc_id].x += interns[old_i - 1].x;
            interns[loc_id].y += interns[old_i - 1].y;
            interns[loc_id].z += interns[old_i - 1].z;
            interns[loc_id].w += interns[old_i - 1].w;
          }
        }
      }
      if (loc_id == 0) result[group_id] = interns[0];
    }
  }

  free(interns);
}

void rsquaredOMP(
    data_t* dataset,
    float mean,
    float2 equation,  // [a0,a1]
    rsquared_t* result,
    int gpu_size,
    int global_size)
{
  rsquared_t* dist = (rsquared_t*)malloc(sizeof(rsquared_t) * local_size);

  for (int group_id = (gpu_size / local_size); group_id < (global_size / local_size); group_id++) {
    for (int loc_id = local_size - 1; loc_id >= 0; loc_id--) {
      int glob_id = loc_id + group_id * local_size;
      dist[loc_id].x = powf((dataset[glob_id].x - mean), 2.f);
      float y_estimated = dataset[glob_id].x * equation.x + equation.y;
      dist[loc_id].y = powf((y_estimated - mean), 2.f);
      for (int i = (local_size / 2), old_i = local_size; i > 0; old_i = i, i /= 2) {
        if (loc_id < i) {
          dist[loc_id].x += dist[loc_id + i].x;
          dist[loc_id].y += dist[loc_id + i].y;
          if (loc_id == (i - 1) && old_i % 2 != 0) {
            dist[loc_id].x += dist[old_i - 1].x;
            dist[loc_id].y += dist[old_i - 1].y;
          }
        }
      }
      if (loc_id == 0) {
        result[group_id] = dist[0];
      }
    }
  }

  free(dist);
}

static
void r_squared(linear_param_t *params, data_t *dataset, sum_t *linreg, result_t *response) 
{
  float mean = linreg->y / params->size;
  float2 equation = {response->a0, response->a1};

  const size_t wg_count = params->wg_count;
  const size_t wg_size = params->wg_size;
  const size_t size = params->size;

  rsquared_t *results = (rsquared_t*) malloc(sizeof(rsquared_t) * wg_count);

  size_t globalWorkSize = size;
  if (size % wg_size) globalWorkSize += wg_size - (size % wg_size);

  size_t cpu_global_size = cpu_offset * globalWorkSize / 100;
  if (cpu_global_size % wg_size != 0) {
      cpu_global_size = (1 + cpu_global_size / wg_size) * wg_size;
  }

  size_t gpu_global_size = globalWorkSize - cpu_global_size;

  if (gpu_global_size > 0) {
    #pragma omp target data map (to: dataset[0:size])\
                            map (alloc: results[0:wg_count])
    {
      const int nTeams = gpu_global_size / wg_size;

      auto start = std::chrono::steady_clock::now();

      for (int i = 0; i < params->repeat; i++)
        rsquared(nTeams, dataset, mean, equation, results);

      auto end = std::chrono::steady_clock::now();
      auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
      response->ktime += time;

      #pragma omp target update from (results[0:(wg_count * (100-cpu_offset) / 100)])
    }
  }

  if (cpu_offset > 0) {
    rsquaredOMP(dataset, mean, equation, results, gpu_global_size, params->size);
  }

  rsquared_t final_result = {0.f, 0.f};

  for (size_t i = 0; i < wg_count; i++) {
    final_result.x += results[i].x;
    final_result.y += results[i].y;
  }

  response->rsquared = final_result.y / final_result.x * 100;

  free(results);
}

void parallelized_regression(linear_param_t *params, data_t *dataset, result_t *response) 
{
  const size_t size = params->size;
  const size_t wg_size = params->wg_size;
  const size_t wg_count = params->wg_count;

  /* Data and buffers */
  sum_t *results = (sum_t *) malloc(sizeof(sum_t) * wg_count);

  size_t globalWorkSize = size;
  if (size % wg_size) globalWorkSize += wg_size - (size % wg_size);

  size_t cpu_global_size;
  cpu_global_size = cpu_offset * globalWorkSize / 100;
  if (cpu_global_size % wg_size != 0) {
    cpu_global_size = (1 + cpu_global_size / wg_size) * wg_size;
  }

  size_t gpu_global_size;
  gpu_global_size = globalWorkSize - cpu_global_size;

  if (gpu_global_size > 0) {
    /* Create data buffer */
    #pragma omp target data map (to: dataset[0:size])\
                            map (alloc: results[0:wg_count])
    {
      const int nTeams = gpu_global_size / wg_size;

      auto start = std::chrono::steady_clock::now();

      for (int i = 0; i < params->repeat; i++)
        linear_regression(nTeams, dataset, results);

      auto end = std::chrono::steady_clock::now();
      auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
      response->ktime += time;

      #pragma omp target update from (results[0:(wg_count * (100-cpu_offset) / 100)])
    }
  }

  if (cpu_offset > 0) {
    linear_regressionOMP(dataset, results, gpu_global_size, size);
  }

  /* Finalize algorithm */
  sum_t final_result = {0.f, 0.f, 0.f, 0.f};

  for (size_t i = 0; i < wg_count; i++) {
    final_result.x += results[i].x;
    final_result.y += results[i].y;
    final_result.z += results[i].z;
    final_result.w += results[i].w;
  }

  double denom = (size * final_result.w - (final_result.x * final_result.x));
  response->a0 = (final_result.y * final_result.w - final_result.x * final_result.z) / denom;
  response->a1 = (size * final_result.z - final_result.x * final_result.y) / denom;
#ifdef DEBUG
  printf("%f %f %f\n", denom, response->a0, response->a1);
#endif

  /* Deallocate resources  */
  free(results);

  r_squared(params, dataset, &final_result, response);
}

