      maskProbableLetters(size,seqBeg, probabilities, maskTable);
    }
  }

  message_stream << "Total time (maskSequences) on the device = " <<
    t.getElapsedTimeInMicroSec() / 1e6 << " s" << std::endl;

  free(probMat_device);
  free(mask_table_device);
  return seqs_device;
}

